/*<info serverAlias="DBCUST-CUSTDB" selecters="bodbAdminNet,bodbDownlineNet,bodbExtAccNet,vnteam" viewers="" isFunction="1"></info>*/
ALTER FUNCTION [dbo].[f_SetBinaryValues] (@binStr VARBINARY(256), @xmlStr XML)   
RETURNS TABLE  
AS  
/*
	Created: Viet @ 14.DEC.2018
	DB: DBCust/custDB

	Revision:     
		- 20181212@Viet: Initial SP [Redmine: #105338]
	Param's Explanation:   
		@xmlStr:   
			+ FORMAT: <root><r pos="" val="" /></root>  
			+ r: row  
			+ pos: Byte's position  
			+ val: new value
	Example: 
		SELECT a.custid, a.discount, b.binaryStr_new
		FROM CS_CustDiscount_Agent a WITH(NOLOCK)
			CROSS APPLY dbo.f_SetBinaryValues(a.discount, '<root><r pos="1" val="111"/><r pos="2" val="222"/></root>') as b
		WHERE a.custid in (19235084, 19235094)
*/ 
RETURN  (
	WITH s AS(
		SELECT	uStr = CONVERT(binary(256), STUFF(CONVERT(binary(256), '0x00', 1), bytePos, 1, CONVERT(BINARY(1), byteValue))),
				mStr = CONVERT(binary(256), STUFF(CONVERT(binary(256), '0x00', 1), bytePos, 1, CONVERT(BINARY(1), '0xFF', 1)))
		FROM (
			SELECT	bytePos = T.C.value('./@pos', 'tinyint'),
					byteValue = T.C.value('./@val', 'tinyint')
			FROM @xmlStr.nodes('/root/r') as [T](C) --T: table, C: column
